$$\begin{equation*}
D_{c}^{(\sigma)} \frac{1}{\gamma^{\prime}}=(-1)^{\sigma} \frac{(2 \sigma)!}{2^{2 \sigma} \sigma!}\left(\xi^{\sigma}+\eta^{\sigma}\right) \frac{1}{\gamma^{2 \sigma+1}}, \tag{66}
\end{equation*}$$

in which we may write

$$\begin{equation*}
\frac{i}{2}\left(\eta^{\sigma}-\xi^{\sigma}\right)=\rho^{\sigma} \sin \sigma \phi, \quad \frac{1}{2}\left(\xi^{\sigma}+\eta^{\sigma}\right)=\rho^{\sigma} \cos \sigma \phi . \tag{67}
\end{equation*}$$


We have now only to differentiate with respect to $z$, which we
 may do so as to obtain the result either in terms of $p$ and $z$, or as
 a homogeneous function of $z$ and $\rho$ divided by a power of $r$,

$$\begin{align*}
d z^{n-\sigma} \frac{1}{r^{2 \sigma+1}}=(-1)^{n-\sigma} \frac{(2 n)!}{2^{n} n!} \frac{2^{\sigma} \sigma!}{(2 \sigma)!} \frac{1}{r^{2 n+1}} \times & \\
& {\left[z^{n-\sigma}-\frac{(n-\sigma)(n-\sigma-1)}{2(2 n-1)} z^{n-\sigma-2} r^{2}+\& \mathrm{c} .\right] * } \tag{68}
\end{align*}$$

$$\text { or } \begin{align*}
\frac{d^{n-\sigma}}{d z^{n-\sigma}} \frac{1}{r^{2 \sigma+1}}= & (-1)^{n-\sigma} \frac{(n+\sigma)!}{(2 \sigma)!} 1 \\
& {\left[z^{n-\sigma}-\frac{(n-\sigma)(n-\sigma-1)}{4(\sigma+1)} z^{n-\sigma-2} \rho^{2}+\& \mathrm{c} .\right] } \tag{69}
\end{align*}$$


If we write

$$\begin{align*}
\Theta_{n}^{(\sigma)} & =\nu^{\sigma}\left[\mu^{n-\sigma}-\frac{(n-\sigma)(n-\sigma-1)}{2(2 n-1)} \mu^{n-\sigma-2}\right. \\
& \left.+\frac{(n-\sigma)(n-\sigma-1)(n-\sigma-2)(n-\sigma-3)}{2 \cdot 4(2 n-1)(2 n-3)} \mu^{n-\sigma-4}-\& \mathrm{c} .\right] \tag{70}
\end{align*}$$

and

$$\begin{align*}
& \mathcal{L}_{n}^{(\sigma)}=\nu^{\sigma}\left[\mu^{n-\sigma}-\frac{(n-\sigma)(n-\sigma-1)}{4(\sigma+1)} \mu^{n-\sigma-2} \nu^{2}\right. \\
& \left.\quad+\frac{(n-\sigma)(n-\sigma-1)(n-\sigma-2)(n-\sigma-3)}{4.8(\sigma+1)(\sigma+2)} \mu^{n-\sigma-4} \nu^{4}-\& \mathrm{c} .\right] \tag{71}
\end{align*}$$

then

$$\begin{equation*}
\Theta_{n}^{(\sigma)}=\frac{2^{n-\sigma} n!(n+\sigma)!}{(2 n)!\sigma!} L_{n}^{(\sigma)}, \tag{72}
\end{equation*}$$

so that these two functions differ only by a constant factor.

We may now write the expressions for the two tesseral har
monics of order $n$ and type $\sigma$ in terms either of $\Theta$ or $\mathscr{I}$,

$$\begin{align*}
Y_{n}^{(\sigma)} & =\frac{(2 n)!}{2^{n+\sigma} n!n!} \Theta_{n}^{(\sigma)} 2 \sin \sigma \phi=\frac{(n+\sigma)!}{2^{2 \sigma} n!\sigma!} \Omega_{n}^{(\sigma)} 2 \sin \sigma \phi  \tag{73}\\
Y_{n}^{(\sigma)} & =\frac{(2 n)!}{2^{n+\sigma} n!n!} \Theta_{n}^{(\sigma)} 2 \cos \sigma \phi=\frac{(n+\sigma)!}{2^{2 \sigma} n!\sigma!} \Omega_{n}^{(\sigma)} 2 \cos \sigma \phi \dagger \tag{74}
\end{align*}$$

* \{Equation (68) may easily be proved by noticing that the left-hand side is $(n-\sigma)$ !
 times the coefficient of $\mathrm{h}^{n-\sigma}$ in $\left\{\frac{1}{\xi \eta+(z+h)^{2}}\right\}^{\frac{2 \sigma+1}{2}}$, or $\frac{1}{r^{2 \sigma+1}}\left\{1+\frac{2 h z+h^{2}}{r^{2}}\right\}^{-\frac{(2 \sigma+1)}{2}}$; if
 we write this as $\frac{1}{r^{2 \sigma}}\left\{\left(1+\mu \frac{h}{r}\right)^{2}+\nu^{2} \frac{h^{2}}{r^{2}}\right\}^{-\frac{(2 \sigma+1)}{2}}$ and pick out the coefficient of $h^{n-\sigma}$,
 we get equation (69). \}

$\dagger$ \{This value must le halved when $\sigma=0$.\}
